import 'dart:convert';
import 'dart:typed_data';

import 'package:archive/archive.dart';

import '../core/errors.dart';
import 'templates.dart';

/// Top-level folders the factory owns; anything the AI writes there is dropped.
const Set<String> _blockedTopLevel = {
  'android',
  'ios',
  'web',
  'linux',
  'macos',
  'windows',
  'build',
  '.dart_tool',
  '.github',
  '.idea',
};

class SanitizeResult {
  const SanitizeResult(this.files, this.dropped);

  final Map<String, String> files;
  final List<String> dropped;
}

/// Removes platform folders and CI files generated by the AI.
SanitizeResult sanitizeFiles(Map<String, String> files) {
  final kept = <String, String>{};
  final dropped = <String>[];
  files.forEach((path, content) {
    final top = path.split('/').first;
    if (path.contains('/') && _blockedTopLevel.contains(top)) {
      dropped.add(path);
    } else {
      kept[path] = content;
    }
  });
  return SanitizeResult(kept, dropped);
}

/// Adds the CI workflow (always) and default config files (if missing).
Map<String, String> injectStandardFiles(
  Map<String, String> files,
  String projectName,
) {
  final result = Map<String, String>.of(files);
  result[workflowPath] =
      workflowTemplate.replaceAll('__PROJECT_NAME__', projectName);
  result.putIfAbsent('.gitignore', () => gitignoreTemplate);
  result.putIfAbsent(
    'analysis_options.yaml',
    () => (files['pubspec.yaml'] ?? '').contains('flutter_lints')
        ? analysisOptionsWithLints
        : analysisOptionsMinimal,
  );
  return result;
}

/// Packs the project into an in-memory ZIP archive.
Uint8List buildZip(Map<String, String> files) {
  final archive = Archive();
  final names = files.keys.toList()..sort();
  for (final name in names) {
    final bytes = utf8.encode(files[name]!);
    archive.addFile(ArchiveFile(name, bytes.length, bytes));
  }
  final encoded = ZipEncoder().encode(archive);
  if (encoded == null) {
    throw FactoryException('تعذّر إنشاء ملف ZIP.');
  }
  return Uint8List.fromList(encoded);
}
